	samples          []metrics.HostSample
	dockerAgg        docker.Aggregate
	dockerSamples    []float64
	dockerMemSamples []float64
	dockerRead       bool
	wsDisk           metrics.DiskUsage
	wsSize           metrics.TreeSize
	posture          posture

	// Loading flags
	loadingServices   bool
	loadingForge      bool
	loadingDocker     bool
	loadingOCI        bool
	loadingWorkspaces bool

	// measuringSize is not a loading flag: it **excludes** a second walk as
	// long as the first one hasn't answered. It's the only dashboard call
	// whose duration grows with the user's data, so the only one that can
	// overrun its interval — and two concurrent walks would double the I/O
	// for a figure already on its way.
	measuringSize bool

	// Refresh
	refreshInterval time.Duration

	// blurred is true while the terminal window has lost the focus
	// (DEVDESK-210). The three clocks keep their timers but skip the I/O.
	blurred bool

	// footer is the one line of transient state below the viewport (Rule 128).
	// The dashboard budgets an info line and left it permanently empty; a key
	// the header greys out has to be able to say why it declined (Rule 130).
	footer sharedcomponents.FooterMessage

	// jobs is the router's snapshot of what is running. The dashboard starts
	// none of it and shows only the count — it is the one screen a user is
	// likely to be looking at while a batch runs somewhere else, which is
	// exactly the case D67 made possible and D9 has to answer for.
	jobs []jobs.Run
}

// New creates a new dashboard model
func New(cfg *config.Config, state *shared.State) Model {
	return Model{
		config:            cfg,
		shared:            state,
		serviceStatus:     shared.ServiceStatusUnknown,
		loadingServices:   true,
		loadingForge:      true,
		loadingDocker:     true,
		loadingOCI:        true,
		loadingWorkspaces: true,
		// Init() starts the walk: the flag is therefore raised right at
		// construction, otherwise the first slow tick would start a second
		// one.
		measuringSize:   true,
		refreshInterval: time.Duration(cfg.Status.RefreshInterval) * time.Second,
	}
}

// Init initializes the dashboard by loading all data
func (m Model) Init() tea.Cmd {
	return tea.Batch(
		m.checkServices(),
		m.fetchForgeStats(),
		m.fetchDockerStats(),
		m.fetchOCIStats(),
		m.fetchWorkspaceStats(),
		m.scheduleRefresh(),
		m.sampleHost(),
		m.scheduleHostTick(),
		m.fetchDockerMetrics(),
		m.scheduleDockerTick(),
		m.fetchDiskUsage(),
		m.measureWorkspaceSize(),
		m.fetchPosture(),
	)
}

// Update handles messages
func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		// A terminal that grows up to `wide` puts the Resources boxes on
		// screen and removes the tab: staying on it would leave the view on a
		// tab that no longer exists.
		if m.activeTab >= dashboardTab(tabCountFor(layoutTier(m.width, m.height))) {
			m.activeTab = tabOverview
		}

	case tea.KeyPressMsg:
		return m.handleKeyMsg(msg)

	case jobs.ChangedMsg:
		m.jobs = msg.Runs
		return m, nil

	case jobs.FrameMsg:
		m.footer.SetBlinkPhase(msg.Blink)
		return m, nil

	case StatusCheckMsg:
		return m.handleStatusCheck(msg)

	case ForgeStatsMsg:
		return m.handleForgeStats(msg)

	case DockerStatsMsg:
		return m.handleDockerStats(msg)

	case OCIStatsMsg:
		return m.handleOCIStats(msg)

	case WorkspaceStatsMsg:
		return m.handleWorkspaceStats(msg)

	case shared.TerminalFocusMsg:
		return m.handleTerminalFocus(msg)

	case RefreshTickMsg:
		if m.blurred {
			return m, m.scheduleRefresh()
		}
		return m.alsoMeasuringSize(m.refreshAll())

	case HostTickMsg:
		if m.blurred {
			return m, m.scheduleHostTick()
		}
		return m, tea.Batch(m.sampleHost(), m.scheduleHostTick())

	case HostSampleMsg:
		return m.handleHostSample(msg)

	case DockerTickMsg:
		if m.blurred {
			return m, m.scheduleDockerTick()
		}
		return m, tea.Batch(m.fetchDockerMetrics(), m.scheduleDockerTick())

	case DockerMetricsMsg:
		return m.handleDockerMetrics(msg)

	case DiskUsageMsg:
		m.wsDisk = msg.Workspaces

	case WorkspaceSizeMsg:
		m.wsSize = msg.Size
		m.measuringSize = false

	case PostureMsg:
		m.posture = msg.Posture
	}

	// The footer consumes the expiry addressed to it; a message posted without
	// its timer being handled never clears (Rule 128).
	m.footer.Handle(msg)

// dashboard is the only view that doesn't frame a single object — see
// View().
func (m Model) Frameless() bool {
	return true
}

// GetFooterHeight returns the footer height for this view (Rule 124): an empty
// line, an info line, and the tab bar when there is more than one tab.
func (m Model) GetFooterHeight() int {
	if m.showsTabBar() {
		return 3
	}
	return 2
}

// showsTabBar reports whether a tab bar is worth a line. A single tab is
// not a choice: the bar would say "you are here", which the screen already
// says.
func (m Model) showsTabBar() bool {
	return tabCountFor(layoutTier(m.width, m.height)) > 1
}

// RenderFooter draws the tab bar (Rule 124).
//
// **There is no "Updated" line**, and its absence is a choice. It used to
// exist to date values stuck at `-`, but the dashboard's three clocks run
// at the second, the five-second, and the thirty-second mark: the oldest
// fact on screen is never a minute old, so TimeAgo permanently answered
// `now`. A line whose value never changes tells nothing, and it was costing
// the view's only info line.
//
// The info line is still rendered even empty: the router budgets on
// GetFooterHeight (Rule 124). It's also what carries the refusal of a
// greyed key (Rule 130) — the line already existed, it was just always
// empty.
func (m Model) RenderFooter(width int) string {
	info := m.footer.View(width, m.status())

	if !m.showsTabBar() {
		return theme.EmptyLineBg(width) + "\n" + info
	}

	tabs := []theme.TabItem{{Label: "Overview"}, {Label: "Resources"}}
	tabBar := theme.PadWithBg(theme.Bg(" ")+theme.RenderTabs(tabs, int(m.activeTab)), width)
	return tabBar + "\n" + theme.EmptyLineBg(width) + "\n" + info
}

// status is the line the dashboard derives on every frame (Rule 128).
//
// The dashboard launches nothing, so it passes no origin and always gets D9's
// degraded form — "2 jobs running — :jobs for details". That is not a
// limitation here but the right sentence: it is the screen a user is most
// likely to be watching while a batch runs somewhere else, and what it can
// honestly say is how much is going and where to look.
func (m Model) status() sharedcomponents.Status {
	line := sharedcomponents.JobsStatusLine(m.jobs, "")
	if line == "" {
		return sharedcomponents.Status{}
	}
	return sharedcomponents.Status{Text: line, Activity: true}
}

// GetShortcuts returns the keyboard shortcuts for the header.
//
// Rule 130: the two deep links need a session and `tab` needs a second tab.
// Neither is a different screen, so the entries stay where they are and are
// greyed — the column is the same six lines at every width and either side of
// a sign-in.
func (m Model) GetShortcuts() shortcut.Shortcuts {
	links := m.forgeLinks()
	return []shortcut.Shortcut{
		// At `wide` the Resources boxes are already on screen, so there is no
		// second tab to switch to.
		{Key: "tab", Description: "Switch tab", Disabled: !m.showsTabBar()},
		{Key: "ctrl+r", Description: "Refresh"},
		{Key: keymap.Requests, Description: "Open MRs", Disabled: !links.Enabled()},
		{Key: keymap.Issues, Description: "Open issues", Disabled: !links.Enabled()},
		{Key: "?", Description: "Help"},
	}
}

// GetTitle returns the view title
func (m Model) GetTitle() string {
	return theme.IconDashboard + " Dashboard"
}

// GetIcon returns the view icon
func (m Model) GetIcon() string {
	return ""
}

// GetHeaderInfo returns the key-value info for the header.
//
// The version is here and on no other screen: the dashboard is the landing
// view, so the only one where the information is read without having been
// sought. Repeating it everywhere would cost a header column on every view
// for a value that never changes during a session; `:about` breaks it
// down.
func (m Model) GetHeaderInfo(context string) []shortcut.HeaderInfo {
	return []shortcut.HeaderInfo{
		{Key: "Context", Value: context, Style: theme.HeaderValueStyle},
		{Key: "Version", Value: version.Get().Short(), Style: theme.HeaderValueStyle},
	}
}

// GetHelpContent returns help content for the dashboard (Rule 114)
func (m Model) GetHelpContent() help.Content {
	v := m.vocab()
	return help.Content{
		Title:       "Dashboard",
		Description: "The dashboard groups everything it knows into four titled boxes: Code, Health, Host and Docker. The layout follows the terminal's size — one column when it is narrow, a grid when it is not, and a third column on a large terminal, where it shows the Resources tab inline. A value that has not been measured yet reads '-', a source that is absent reads 'n/a', and a measured zero reads '0'.",
		KeyBindings: []help.KeyBinding{
			{Key: "tab", Description: "Switch between the Overview and Resources tabs"},
			{Key: "ctrl+r", Description: "Refresh all dashboard data, and detect the tools again"},
			{Key: keymap.Requests, Description: "Open assigned merge requests in browser (requires authentication)"},
			{Key: keymap.Issues, Description: "Open assigned issues in browser (requires authentication)"},
			{Key: "ctrl+p", Description: "Open command mode to navigate to other views"},
			{Key: "?", Description: "Show this help"},
		},
		Sections: []help.Section{
			{
				Title: "Code",
				Body: "Your " + v.Name + " activity — assigned " + strings.ToLower(v.ChangeRequests) + ", " +
					strings.ToLower(v.ChangeRequests) + " awaiting your review, assigned issues —" +
					" and the local clones under the workspaces directory. The two belong together: the explorer " +
					"creates what does not exist, workspaces reconciles what does. Requires authentication via :" +
					string(command.ViewGitAuth) + ".",
			},
			{
				Title: "Health",
				Body:  "Monitored services (HTTP, ICMP, DNS) and SSL certificates, each with its up and down counts, plus the security posture read from the scan caches. Monitors are configured in :status, and the findings themselves live in :security — this box only counts them.",
			},
			{
				Title: "Host and Docker",
				Body:  "Two measurement points, and they are not on one axis: the Host box reads the machine dk runs on, while the Docker box reads inside the Docker Desktop VM, whose footprint is a subset of the host's. Both are true and they do not add up, which is why the box titles name where the number was measured.\n\nThe Host box ends on the tooling, in one line: whether every tool this context needs is there. Needed means the container engine, git, and each scanner ticked in a scan category that is on (:config, scan tab) — a tool nobody ticked is never missing. The tools are detected at start, on a context switch, when a tool's source, binary or image is saved, and on ctrl+r: one installed while dk runs is seen after ctrl+r. The Docker box counts what the daemon holds under a Resources root: images, volumes and networks. The sizes are not there, they are in Storage.",
			},
			{
				Title: "Resources",
				Body:  "The second tab carries the host and Docker series in detail — throughput, disk per volume, reclaimable space. It exists because nothing else shows them: there is no host view, and :containers shows one container rather than the machine. On a large terminal it is inline in a third column and the tab is a bigger version of it.",
			},

// isn't monitored, which is the opposite of what a zero means.
//
// Certificates no longer go through here — see certBranches, and
// status.CertState for what tells them apart.
func statusBranches(components []status.ComponentStatus, loading bool) []string {
	nodes := func(up, down, errValue string) []string {
		return []string{
			narrowBranch(false, "up", up),
			narrowBranch(false, "down", down),
			narrowBranch(true, "error", errValue),
		}
	}

	switch {
	case loading:
		return nodes(unknownValue(), unknownValue(), unknownValue())
	case len(components) == 0:
		return nothingConfigured(len(nodes("", "", "")))
	default:
		ok, down, errCount := countStatuses(components)
		return nodes(
			countValue(ok),
			alertCount(down, theme.StatusDownStyle),
			alertCount(errCount, theme.StatusErrorStyle),
		)
	}
}

// certBranches renders one node per certificate state, then the nearest
// expiry.
//
// **The vocabulary is not the monitors', and that was the bug.** A
// certificate rendered under `up` / `down` / `error` put an expired
// certificate, one expiring next week, and one that couldn't be read —
// SSLChecker gives `ERROR` to all three — into the same bucket, while `up`
// named "reachable" which means "valid". The four states of
// status.CertState tell them apart, and the one line that calls for action —
// `to renew` — stops being drowned in the other two.
//
// The expiry stays its own node: `to renew` says how many, it says when,
// and two figures on one line require remembering which is which (that's
// what postureBranches already settled).
func certBranches(certs []status.ComponentStatus, loading bool, expiry string) []string {
	nodes := func(valid, toRenew, expired, errValue string) []string {
		return []string{
			narrowBranch(false, "valid", valid),
			narrowBranch(false, "to renew", toRenew),
			narrowBranch(false, "expired", expired),
			narrowBranch(false, "error", errValue),
			narrowBranch(true, "expiry", expiry),
		}
	}

	switch {
	case loading:
		return nodes(unknownValue(), unknownValue(), unknownValue(), unknownValue())
	case len(certs) == 0:
		return nothingConfigured(len(nodes("", "", "", "")))
	default:
		valid, toRenew, expired, errored := status.CertCounts(certs)
		return nodes(
			countValue(valid),
			certAlert(toRenew, status.CertToRenew),
			certAlert(expired, status.CertExpired),
			certAlert(errored, status.CertError),
		)
	}
}

// certGlyph reads one state's glyph and colour from the theme rather than
// naming them here: `:status` renders the same column, and two lookup
// tables would eventually diverge on the one that matters — the one that
// tells `expired` apart from `error`. It backs certSummary, the single-line
// form these counts also take at the `standard` tier; the tree nodes below
// (certAlert) carry no icon — see alertCount.
func certGlyph(state status.CertState) string {
	return endGlyph(theme.CertStateStyle(string(state)), theme.CertStateIcon(string(state)))
}

